function createVideoProject(title='新的视频项目',script=''){
 const project={id:uid(),title,platform:'抖音',aspectRatio:'9:16',resolution:720,captionPosition:'bottom',captionSize:'medium',captionColor:'#ffffff',audioVolume:35,script,shots:[],audioAssetId:'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};
 data.videoProjects.push(project);activeVideoProjectId=project.id;page='视频工坊';if(save()){render();window.scrollTo(0,0);toast('视频项目已在本机创建')}
}
function videoProject(id){return data.videoProjects.find(project=>project.id===id)}
function updateVideoProject(project){project.updatedAt=new Date().toISOString();save()}
function updateVideoStatus(message){videoRenderStatus=message;const element=document.querySelector('#video-render-status');if(element){element.textContent=message;element.classList.toggle('hidden',!message)}}
async function renderVideoProject(id){
 if(videoRenderBusy)return toast('已有视频正在导出');
 if(videoAiBusy)return toast('请等待本机模型完成分镜整理');
 const project=videoProject(id);if(!project)return toast('找不到视频项目');if(!project.shots?.length)return toast('请先创建至少一个镜头');
 videoRenderBusy=true;videoRenderController=new AbortController();updateVideoStatus('正在准备离线渲染…');render();
 try{
  const snapshot=structuredClone(project);
  const blob=await renderLocalVideo(snapshot,{getAsset:getFile,signal:videoRenderController.signal,onProgress:progress=>updateVideoStatus(`离线渲染中：镜头 ${progress.shot}/${progress.totalShots} · ${Math.floor(progress.completedSeconds)} / ${progress.totalSeconds} 秒`) });
  const assetId=uid(),previousExportAssetId=project.exportAssetId,extension=outputExtension(blob),fileName=`${(project.title||'视频作品').replace(/[\\/:*?"<>|]/g,'_')}.${extension}`;
  await saveFile(assetId,blob);
  const asset={id:assetId,title:`${project.title||'视频作品'} · 离线成片`,type:'视频',fileId:assetId,fileName,mime:blob.type||'video/webm',size:blob.size,tags:'离线成片',projectId:project.id};
  data.assets.push(asset);project.exportAssetId=assetId;project.updatedAt=new Date().toISOString();
  if(!save()){data.assets.pop();if(previousExportAssetId)project.exportAssetId=previousExportAssetId;else delete project.exportAssetId;await removeFile(assetId);save();return}
  videoRenderStatus='导出完成。文件已保存到本地素材库，可在此预览或下载。';toast('离线视频已导出并保存到素材库');
 }catch(error){videoRenderStatus=error.name==='AbortError'?'导出已取消。':`导出未完成：${error.message}`;if(error.name!=='AbortError')toast(error.message)}
 finally{videoRenderBusy=false;videoRenderController=null;render()}
}
document.addEventListener('click',async e=>{
 const buttonElement=e.target.closest('[data-action]');if(!buttonElement)return;
 const action=buttonElement.dataset.action,[,legacyProjectId,legacyShotId]=action.split(':');
 const projectId=buttonElement.dataset.projectId||legacyProjectId,shotId=buttonElement.dataset.shotId||legacyShotId;
 if(action==='musetalk-check'){await refreshMuseTalk(true);return}
 if(action==='musetalk-run'){await runMuseTalk();return}
 if(action==='musetalk-save'){await saveMuseTalkOutput(buttonElement.dataset.jobId);return}
 if(action==='video-new'){createVideoProject();return}
 if(action==='video-open'){activeVideoProjectId=projectId;page='视频工坊';videoRenderStatus='';render();return}
 if(action==='video-delete'){const project=videoProject(projectId);if(!project)return;if(videoAiBusy||data.videoPending?.projectId===projectId)return toast('该项目有本机模型任务正在运行或待恢复，请先完成任务');if(!confirm(`删除视频项目“${project.title}”？导出的素材文件会保留在素材库。`))return;data.videoProjects=data.videoProjects.filter(item=>item.id!==projectId);activeVideoProjectId=data.videoProjects.at(-1)?.id||'';save();render();toast('视频项目已删除，导出文件仍保留在素材库');return}
 if(action==='video-split'){if(videoAiBusy)return toast('请等待本机模型处理完成');const project=videoProject(projectId);if(!project)return;if(!String(project.script||'').trim())return toast('请先粘贴视频脚本');if(project.shots?.length&&!confirm('重新拆分会替换当前镜头清单，确定继续吗？'))return;project.shots=splitScriptIntoShots(project.script).map((shot,index)=>({...shot,id:uid(),title:`镜头 ${index+1}`}));updateVideoProject(project);render();toast(`已离线拆分为 ${project.shots.length} 个镜头`);return}
 if(action==='video-ai-split'){await videoAiSplit(projectId);return}
 if(action==='video-ai-resume'){await videoAiSplit(projectId,true);return}
 if(action==='video-add-shot'){const project=videoProject(projectId);if(!project)return;project.shots||=[];project.shots.push({id:uid(),title:`镜头 ${project.shots.length+1}`,visual:'',voiceover:'',caption:'',duration:5,motion:'none',transition:'cut',assetId:''});updateVideoProject(project);render();return}
 if(action==='video-delete-shot'){const project=videoProject(projectId);if(!project)return;if(!confirm('删除这个镜头？'))return;project.shots=project.shots.filter(shot=>shot.id!==shotId);updateVideoProject(project);render();return}
 if(action==='video-move'){const project=videoProject(projectId);if(!project)return;const index=project.shots.findIndex(shot=>shot.id===shotId),next=index+(buttonElement.dataset.direction==='up'?-1:1);if(index<0||next<0||next>=project.shots.length)return;[project.shots[index],project.shots[next]]=[project.shots[next],project.shots[index]];updateVideoProject(project);render();return}
 if(action==='video-srt'){const project=videoProject(projectId);if(!project?.shots?.length)return toast('没有可导出的字幕');download(`${(project.title||'视频字幕').replace(/[\\/:*?"<>|]/g,'_')}.srt`,`\ufeff${storyboardToSrt(project)}`,'text/plain;charset=utf-8');toast('SRT 字幕已导出');return}
 if(action==='video-render'){await renderVideoProject(projectId);return}
 if(action==='video-cancel'){videoRenderController?.abort();updateVideoStatus('正在停止导出…');return}
 if(action==='video-download'){const project=videoProject(projectId),asset=data.assets.find(item=>item.id===project?.exportAssetId);if(!asset?.fileId)return toast('没有找到导出文件');const blob=await getFile(asset.fileId);if(!blob)return toast('导出文件无法读取');download(asset.fileName||'视频作品.webm',blob,asset.mime||blob.type);return}
});
function updateVideoField(target){
 const project=videoProject(target.dataset.projectId);if(!project)return;
 const field=target.dataset.videoProjectField;
 if(field){project[field]=target.value;if(field==='title'){const heading=document.querySelector('.video-editor-top h2');if(heading)heading.textContent=target.value||'未命名视频项目'}updateVideoProject(project);return}
 const shot=project.shots?.find(item=>item.id===target.dataset.shotId);if(!shot)return;
 if(target.hasAttribute('data-video-shot-asset'))shot.assetId=target.value;
 else{const fieldName=target.dataset.videoShotField;if(!fieldName)return;shot[fieldName]=fieldName==='duration'?Math.min(60,Math.max(1,Number(target.value)||1)):target.value}
 updateVideoProject(project);
}
document.addEventListener('input',e=>{if(e.target.matches('[data-video-project-field], [data-video-shot-field]'))updateVideoField(e.target)});
document.addEventListener('change',e=>{
 if(e.target.matches('[data-video-project-field], [data-video-shot-field], [data-video-shot-asset]')){updateVideoField(e.target);if(e.target.hasAttribute('data-video-shot-asset'))render();return}
 if(e.target.id==='video-draft-select'&&e.target.value){const draft=data.drafts.find(item=>item.id===e.target.value),project=videoProject(activeVideoProjectId);if(!draft||!project)return;project.script=draft.content||'';project.title=project.title==='新的视频项目'&&draft.title?draft.title:project.title;updateVideoProject(project);render();toast('草稿已载入视频项目，请离线拆分分镜')}
});

document.addEventListener('submit',async e=>{if(e.target.id!=='record-form')return;e.preventDefault();let f=e.target,kind=f.dataset.kind,id=f.dataset.id,formdata=new FormData(f),old=data[kind].find(x=>x.id===id)||{},record={...old,id:id||uid()};for(let [key,value] of formdata.entries()){if(key!=='file')record[key]=value}let file=formdata.get('file'),newFileId;if(file?.size){newFileId=uid();record.fileId=newFileId;record.fileName=file.name;record.mime=file.type||'application/octet-stream';record.size=file.size;record.type=assetKind(record.mime);try{await saveFile(newFileId,file)}catch(err){toast('素材保存失败：'+(err.message||'空间不足'));return}}let before=structuredClone(data[kind]);if(id)data[kind]=data[kind].map(x=>x.id===id?record:x);else data[kind].push(record);if(!save()){data[kind]=before;if(newFileId)await removeFile(newFileId).catch(()=>{});return}if(newFileId&&old.fileId)await removeFile(old.fileId).catch(()=>{});document.querySelector('#modal-root').innerHTML='';render();toast('已保存到本地')});
document.addEventListener('change',async e=>{
 if(['cover-size','cover-align'].includes(e.target.id))updateCover();
 if(e.target.id==='cover-image'){const file=e.target.files[0];if(file)try{await saveUploadedCover(file)}catch(err){toast('背景图片未保存：'+err.message)}}
 if(e.target.id==='cover-asset'){try{await applyCoverAsset(e.target.value)}catch(err){toast('无法应用素材：'+err.message)}}
 if(e.target.id==='asset-files'){
  let files=[...e.target.files],saved=0;
  for(const file of files){let id=uid(),rec={id,title:file.name,type:assetKind(file.type),fileId:id,fileName:file.name,mime:file.type||'application/octet-stream',size:file.size,tags:''};try{await saveFile(id,file);data.assets.push(rec);if(!save()){data.assets.pop();await removeFile(id);break}saved++}catch(err){toast(`已导入 ${saved} 个文件，剩余文件未完成：${err.message||'空间不足'}`);break}}
  render();if(saved===files.length)toast(`已导入 ${saved} 个素材`);
 }
 if(e.target.id==='messages-file'){let file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('文件不能超过 5 MB');let imported=csvToMessages(await file.text(),uid),old=data.messages||[],result=mergeMessages(old,imported);if(!result.added){toast(`没有新私信，已跳过 ${result.skipped} 条重复记录`);return}if(!confirm(`将导入 ${result.added} 条私信，跳过 ${result.skipped} 条重复记录。继续吗？`))return;data.messages=result.items;if(!save()){data.messages=old;return}render();toast(`已导入 ${result.added} 条私信，跳过 ${result.skipped} 条重复记录`)}catch(err){toast('导入失败：'+err.message)}}if(e.target.id==='comments-file'){let file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('文件不能超过 5 MB');let imported=csvToComments(await file.text(),uid),old=data.comments||[],result=mergeComments(old,imported);if(!result.added){toast(`没有新评论，已跳过 ${result.skipped} 条重复记录`);return}if(!confirm(`将导入 ${result.added} 条评论，跳过 ${result.skipped} 条重复记录。继续吗？`))return;data.comments=result.items;if(!save()){data.comments=old;return}render();toast(`已导入 ${result.added} 条评论，跳过 ${result.skipped} 条重复记录`)}catch(err){toast('导入失败：'+err.message)}}if(e.target.id==='audience-file'){let file=e.target.files[0];if(!file)return;try{let rows=csvToAudience(await file.text(),uid),previous=data.audience;data.audience=[...previous,...rows];if(!save()){data.audience=previous;return}render();toast(`已导入 ${rows.length} 条粉丝记录`)}catch(err){toast('导入失败：'+err.message)}}if(e.target.id==='csv-file'){
  const file=e.target.files[0];if(!file)return;
  try{const posts=csvToPosts(await file.text(),uid);data.posts.push(...posts);if(!save()){data.posts.splice(-posts.length);return}render();toast(`已导入 ${posts.length} 条内容数据`)}catch(err){toast('导入失败：'+err.message)}
 }
 if(e.target.id==='import-file'){
  const file=e.target.files[0];if(!file)return;
  try{const {payload,files}=await readBackup(file),d=payload.data;if(![1,2].includes(payload.version)||!d||!['topics','tasks','posts','assets','fans','income','drafts'].every(k=>Array.isArray(d[k]))&&['audience','comments','messages'].every(k=>d[k]===undefined||Array.isArray(d[k])))throw Error('备份格式无效');if(!confirm('导入将替换当前工作台数据和素材。建议先导出备份，确定继续吗？'))return;let previous=data;data={...structuredClone(initial),...d,settings:{...initial.settings,...d.settings}};data.settings.theme=normalizeTheme(data.settings.theme);applyTheme(data.settings.theme);if(!save()){data=previous;return}try{await replaceFiles(files||[])}catch(err){data=previous;save();throw err}render();toast('备份已导入')}catch(err){toast('导入失败：'+(err.message||'备份文件无效'))}
 }
});
document.addEventListener('input',e=>{if(e.target.id==='pub-title')publishDraft.title=e.target.value;if(e.target.id==='pub-body')publishDraft.body=e.target.value;if(e.target.id==='pub-schedule')publishDraft.schedule=e.target.value;if(e.target.id==='pub-platform')publishDraft.platform=e.target.value;if(e.target.id==='pub-kind')publishDraft.kind=e.target.value;if(e.target.id==='writer-input')writerInput=e.target.value;if(e.target.id==='writer-output'){output=e.target.innerText;updateWriterWarning()}if(e.target.id==='global-search'){query=e.target.value;let pos=e.target.selectionStart;render();let input=document.querySelector('#global-search');input.focus();input.setSelectionRange(pos,pos)}if(e.target.id?.startsWith('cover-')&&e.target.id!=='cover-image')updateCover()});
render();
